    """Parse a version string."""
    match = _VERSION_RE.fullmatch(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, pre, build = match.groups()
    prerelease = tuple(pre.split(".")) if pre else ()
    for ident in prerelease:
        if _DIGITS_RE.fullmatch(ident) and len(ident) > 1 and ident[0] == "0":
            raise ValueError(f"invalid version: {text!r} (leading zero)")
    return Version(
        int(major),
        int(minor),
        int(patch),
        prerelease,
        tuple(build.split(".")) if build else (),
    )


def _coerce(version: str | Version) -> Version:
    return version if isinstance(version, Version) else parse(version)


def _cmp(x, y) -> int:
    return (x > y) - (x < y)


def _compare_ident(a: str, b: str) -> int:
    a_num, b_num = _DIGITS_RE.fullmatch(a), _DIGITS_RE.fullmatch(b)
    if a_num and b_num:
        return _cmp(int(a), int(b))
    if a_num or b_num:
        return -1 if a_num else 1
    return _cmp(a, b)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _coerce(a), _coerce(b)
    result = _cmp((a.major, a.minor, a.patch), (b.major, b.minor, b.patch))
    if result:
        return result
    if not a.prerelease or not b.prerelease:
        return _cmp(not a.prerelease, not b.prerelease)
    for x, y in zip(a.prerelease, b.prerelease):
        result = _compare_ident(x, y)
        if result:
