            upper = Version(major + 1, 0, 0)
        elif minor:
            upper = Version(0, minor + 1, 0)
        else:
            upper = Version(0, 0, patch + 1)
        return [(">=", version), ("<", upper)]
    if op == "~":
        return [(">=", version), ("<", Version(major, minor + 1, 0))]
    return [(op, version)]


def _holds(version: Version, op: str, bound: Version) -> bool:
    result = compare(version, bound)
    return {
        "=": result == 0,
        ">": result > 0,
        ">=": result >= 0,
        "<": result < 0,
        "<=": result <= 0,
    }[op]


