            raise ValueError(f"invalid range: {range_!r} (empty comparator set)")
        try:
            sets.append([pair for word in words for pair in _comparators(word)])
        except ValueError:
            raise ValueError(f"invalid range: {range_!r}") from None
    core = (version.major, version.minor, version.patch)
    for comparators in sets:
        if version.prerelease and not any(
            bound.prerelease and (bound.major, bound.minor, bound.patch) == core
            for _, bound in comparators
        ):
            continue
        if all(_OPS[op](compare(version, bound)) for op, bound in comparators):
            return True
    return False

    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current: dict[str, str] | None = None
    last_key: str | None = None
    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped[0] in "#;":
            last_key = None
            continue
        if last_key is not None and line[0].isspace():
            current[last_key] += "\n" + stripped
            continue
        last_key = None
        if stripped.startswith("[") and stripped.endswith("]"):
            current = sections.setdefault(stripped[1:-1].strip(), {})
            continue
        positions = [i for i in (stripped.find("="), stripped.find(":")) if i >= 0]
        if not positions:
            raise ParseError(lineno, f"cannot parse {stripped!r}")
        split = min(positions)
        key = stripped[:split].strip().lower()
        if not key:
            raise ParseError(lineno, "empty key")
        if current is None:
            raise ParseError(lineno, f"key {key!r} before any section")
        current[key] = stripped[split + 1 :].strip()
        last_key = key
    return _interpolate(sections)


def _interpolate(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    done: dict[tuple[str, str], str] = {}
    active: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        ref = (section, key)
        if ref in done:
            return done[ref]
        if section not in sections:
            raise InterpolationError(f"no section {section!r}")
        if key not in sections[section]:
            raise InterpolationError(f"no key {key!r} in section {section!r}")
        if ref in active:
            raise InterpolationError(f"cycle at {section}:{key}")
        active.add(ref)
        done[ref] = expand(section, sections[section][key])
        active.discard(ref)
        return done[ref]

    def expand(section: str, value: str) -> str:
        out = []
        i = 0
        while i < len(value):
            if value.startswith("$$", i):
                out.append("$")
                i += 2
                continue
            if value.startswith("${", i):
                end = value.find("}", i + 2)
                if end >= 0:
                    # Keys cannot contain ":", so anything before the last
                    # one is a section name (which may itself contain ":").
                    other, colon, key = value[i + 2 : end].rpartition(":")
                    target = other.strip() if colon else section
                    out.append(resolve(target, key.strip().lower()))
                    i = end + 1
                    continue
            out.append(value[i])
            i += 1
        return "".join(out)

    return {
        name: {key: resolve(name, key) for key in keys}
        for name, keys in sections.items()
    }

