from __future__ import annotations

import re

_ALIGNS = (None, "left", "right", "center")
_DELIMITER = re.compile(r":?-+:?")
_PIPE = re.compile(r"(?<!\\)\|")


def _cell(value: object) -> str:
    """The escaped text of one cell."""
    return "" if value is None else str(value).replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    """Pad ``text`` with spaces to ``width`` according to ``align``."""
    if align == "right":
        return text.rjust(width)
    if align == "center":
        space = width - len(text)
        left = space // 2
        return " " * left + text + " " * (space - left)
    return text.ljust(width)


def _delimiter(width: int, align: str | None) -> str:
    """The delimiter cell for a column of ``width``."""
    first = ":" if align in ("left", "center") else "-"
    last = ":" if align in ("right", "center") else "-"
    return first + "-" * (width - 2) + last


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    if align is None:
        align = [None] * columns
    else:
        align = list(align)
        if len(align) != columns:
            raise ValueError(
                f"align has {len(align)} entries for {columns} columns"
            )
        for value in align:
            if value not in _ALIGNS:
                raise ValueError(f"invalid alignment: {value!r}")

    head = [_cell(value) for value in header]
    body = []
    for row in rows:
        cells = [_cell(value) for value in row]
        if len(cells) > columns:
            raise ValueError(
                f"row has {len(cells)} cells but the header has {columns}"
            )
        body.append(cells + [""] * (columns - len(cells)))

    widths = [
        max([3, len(head[i])] + [len(cells[i]) for cells in body])
        for i in range(columns)
    ]
    lines = [[_pad(c, w, a) for c, w, a in zip(head, widths, align)]]
    lines.append([_delimiter(w, a) for w, a in zip(widths, align)])
    for cells in body:
        lines.append([_pad(c, w, a) for c, w, a in zip(cells, widths, align)])
    return "\n".join(_line(cells) for cells in lines)


def _split(line: str) -> list[str]:
    """Split a table line into stripped, unescaped cells."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    return [cell.strip().replace("\\|", "|") for cell in _PIPE.split(line)]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.strip().splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs a header line and a delimiter line")
    header = _split(lines[0])
    columns = len(header)

    delimiter = _split(lines[1])
    if len(delimiter) != columns:
        raise ValueError(
            f"delimiter line has {len(delimiter)} cells "
            f"but the header has {columns}"
        )
    align: list[str | None] = []
    for cell in delimiter:
        if not _DELIMITER.fullmatch(cell):
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left, right = cell.startswith(":"), cell.endswith(":")
        if left and right:
            align.append("center")
        elif left:
            align.append("left")
        elif right:
            align.append("right")
        else:
            align.append(None)

    rows = []
    for number, line in enumerate(lines[2:], start=3):
        cells = _split(line)
        if len(cells) != columns:
            raise ValueError(
                f"line {number} has {len(cells)} cells "
                f"but the header has {columns}"
            )
        rows.append(cells)
    return header, rows, align

    """Parse an ISO 8601 duration."""
    match = _PATTERN.fullmatch(text)
    if match is None or not any(match.groups()) or text.endswith("T"):
        raise ValueError(f"invalid duration: {text!r}")
    years, months, weeks, days, hours, minutes, seconds = match.groups()
    return Duration(
        years=int(years or 0),
        months=int(months or 0),
        weeks=int(weeks or 0),
        days=int(days or 0),
        hours=int(hours or 0),
        minutes=int(minutes or 0),
        seconds=_parse_seconds(seconds),
    )


def _parse_seconds(text: str | None) -> float:
    if text is None:
        return 0
    if "." in text:
        return float(text)
    return int(text)


def format(duration: Duration) -> str:
    """Write ``duration`` in canonical ISO 8601 form."""
    date = ""
    for value, unit in (
        (duration.years, "Y"),
        (duration.months, "M"),
        (duration.weeks, "W"),
        (duration.days, "D"),
    ):
        date += _format_part(value, unit)
    time = ""
    for value, unit in ((duration.hours, "H"), (duration.minutes, "M")):
        time += _format_part(value, unit)
    seconds = _format_seconds(duration.seconds)
    if seconds != "0":
        time += f"{seconds}S"
    if not date and not time:
        return "PT0S"
    return "P" + date + ("T" + time if time else "")


def _format_part(value: int, unit: str) -> str:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(f"{unit} part must be a non-negative integer: {value!r}")
    return f"{value}{unit}" if value else ""


def _format_seconds(seconds: float) -> str:
    if isinstance(seconds, bool) or not math.isfinite(seconds) or seconds < 0:
        raise ValueError(f"seconds must be finite and non-negative: {seconds!r}")
    return f"{seconds:.{_SECOND_DECIMALS}f}".rstrip("0").rstrip(".")


def add(moment: datetime, duration: Duration) -> datetime:
    """``moment`` plus ``duration``."""
    month_index = moment.month - 1 + duration.years * 12 + duration.months
    year = moment.year + month_index // 12
    month = month_index % 12 + 1
    if not 1 <= year <= 9999:
        raise ValueError(f"year {year} is out of range")
    day = min(moment.day, calendar.monthrange(year, month)[1])
    moment = moment.replace(year=year, month=month, day=day)
    elapsed = timedelta(
        weeks=duration.weeks,
        days=duration.days,
        hours=duration.hours,
        minutes=duration.minutes,
        seconds=duration.seconds,
    )
    if moment.utcoffset() is None:
        return moment + elapsed
    # Aware datetimes: add in UTC so the result is exact elapsed time even
    # across a UTC offset change, then return to the original time zone.
    return (moment.astimezone(timezone.utc) + elapsed).astimezone(moment.tzinfo)

